"""Summarize node event sequences without modifying the node."""
import json
import os
import re
import stat
import sys
from collections import Counter
from pathlib import Path


def reject_constant(value):
    raise ValueError(value)


def decode(data):
    return json.loads(data.decode("utf-8"), parse_constant=reject_constant)


def read_channel(node, channel, names, bad):
    pattern = rf"{channel}\.[0-9]{{12}}\.jsonl"
    files = sorted(
        (name for name in names if re.fullmatch(pattern, name)),
        key=lambda name: int(name[len(channel) + 1:len(channel) + 13]),
    )
    active = f"{channel}.active.jsonl"
    if active in names:
        files.append(active)

    counts = Counter()
    for name in files:
        parts = (node / name).read_bytes().split(b"\n")
        for number, raw in enumerate(parts[:-1], 1):
            try:
                record = decode(raw)
            except (UnicodeError, ValueError):
                bad.append({"file": name, "line": number, "why": "bad_json"})
                continue
            seq = record.get("seq") if isinstance(record, dict) else None
            if type(seq) is not int or seq < 1:
                bad.append({"file": name, "line": number, "why": "no_seq"})
            else:
                counts[seq] += 1
        if parts[-1]:
            bad.append({"file": name, "line": len(parts), "why": "torn"})

    seqs = sorted(counts)
    return {
        "count": sum(counts.values()),
        "first": seqs[0] if seqs else None,
        "last": seqs[-1] if seqs else None,
        "missing": [[a + 1, b - 1] for a, b in zip(seqs, seqs[1:]) if b > a + 1],
        "dup": [seq for seq in seqs if counts[seq] >= 2],
        "next_seq": None,
        "unacked": None,
        "stale_next": None,
    }, seqs


def apply_state(node, channels, sequences):
    path = node / "state.json"
    try:
        info = path.lstat()
    except FileNotFoundError:
        return False
    try:
        if not stat.S_ISREG(info.st_mode):
            return True
        state = decode(path.read_bytes())
    except (OSError, UnicodeError, ValueError):
        return True
    if not isinstance(state, dict) or not isinstance(state.get("channels"), dict):
        return True

    invalid = False
    for name in ("obs", "must"):
        data = state["channels"].get(name)
        if (not isinstance(data, dict)
                or type(data.get("next_seq")) is not int
                or (name == "must" and type(data.get("acked_upto")) is not int)):
            invalid = True
            continue
        result = channels[name]
        result["next_seq"] = data["next_seq"]
        result["stale_next"] = (data["next_seq"] != result["last"] + 1
                                if result["last"] is not None else None)
        if name == "must":
            result["unacked"] = sum(seq > data["acked_upto"] for seq in sequences[name])
    return invalid


def summarize(node):
    with os.scandir(node) as entries:
        names = {entry.name for entry in entries if entry.is_file(follow_symlinks=False)}
    bad = []
    channels = {}
    sequences = {}
    for name in ("obs", "must"):
        channels[name], sequences[name] = read_channel(node, name, names, bad)
    if apply_state(node, channels, sequences):
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})
    bad.sort(key=lambda item: (item["file"], item["line"] or 0, item["why"]))
    return {"v": 1, "channels": channels, "bad": bad}


def main(argv=None):
    args = sys.argv[1:] if argv is None else argv
    if len(args) != 1 or not Path(args[0]).is_dir():
        return 2
    try:
        result = summarize(Path(args[0]))
    except OSError:
        return 2
    print(json.dumps(result, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    sys.exit(main())
